import{_ as i,o as e,c as l,aw as t}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Информация","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react-hooks/main/info.md","filePath":"wiki/dev-commit/framework-react/react-hooks/main/info.md"}'),r={name:"wiki/dev-commit/framework-react/react-hooks/main/info.md"};function o(n,a,c,h,s,d){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h1><h2 id="информация-1" tabindex="-1">Информация <a class="header-anchor" href="#информация-1" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><ul><li><strong>Хуки (React 16.8)</strong> - функции JavaScript, которые позволяют использовать состояние, методы жизненного цикла и другие возможности React из функциональных компонентов</li><li>Хуки позволяют вам повторно использовать логику состояния, не затрагивая дерево компонентов. Благодаря этому, хуки легко использовать в разных компонентах и делиться ими с сообществом</li><li>Хуки работают рядом с существующим кодом, поэтому вы можете внедрять их постепенно</li><li>Не работают внутри классов</li></ul><h2 id="правила-хуков" tabindex="-1">Правила хуков <a class="header-anchor" href="#правила-хуков" aria-label="Permalink to &quot;Правила хуков&quot;">​</a></h2><h3 id="можно-использовать-внутри" tabindex="-1">Можно использовать внутри: <a class="header-anchor" href="#можно-использовать-внутри" aria-label="Permalink to &quot;Можно использовать внутри:&quot;">​</a></h3><ul><li>Функциональные компоненты</li><li>Пользовательские хуки</li></ul><h3 id="нельзя-использовать-внутри" tabindex="-1">Нельзя использовать внутри: <a class="header-anchor" href="#нельзя-использовать-внутри" aria-label="Permalink to &quot;Нельзя использовать внутри:&quot;">​</a></h3><ul><li>Классы</li><li>Обычные JavaScript-функции</li><li>Циклы</li><li>Условия</li><li>Вложенные функции</li></ul><h2 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h2><ul><li>Делают переиспользование удобнее</li><li>Позволяют писать более интуитивно-понятный код</li><li>Избавляют от жизненного цикла</li></ul><h2 id="решаемые-проблемы" tabindex="-1">Решаемые проблемы <a class="header-anchor" href="#решаемые-проблемы" aria-label="Permalink to &quot;Решаемые проблемы&quot;">​</a></h2><ul><li>Трудно повторно использовать логику состояний между компонентами. В React нет способа «присоединить» повторно используемое поведение к компоненту (например, подключение к хранилищу)</li><li>Сложные компоненты становятся трудными для понимания. Каждый метод жизненного цикла часто содержит смесь несвязанной логики. Хуки позволяют разбить один компонент на маленькие функции по их назначению (например, подписке или загрузке данных), а не на основе методов жизненного цикла. Вы также можете контролировать внутреннее состояние с помощью редюсера, чтобы поведение было более предсказуемым</li><li>Классы создают существенный барьер в изучении React. Хуки позволяют использовать больше возможностей React без написания классов. Концептуально, React-компоненты всегда были ближе к функциям</li></ul>',12)])])}const f=i(r,[["render",o]]);export{m as __pageData,f as default};
